SELECT ERR_GROUP_CD  AS err_group_cd
     , DEVICE_ID     AS device_id
     , FINISHED_TIME AS finished_time
  FROM T_ATM_STOP_HISTORY
 WHERE TERM_GROUP_ID = #{termGroupId}
   AND TERM_ID       = #{termId}
   AND JNL_DATE      < #{baseDate}
   AND FINISHED_DATE = #{baseDate}
 ORDER BY JNL_DATE, JNL_TIME

SELECT COUNT(*)
  FROM T_TRANSACTION_JOURNAL
 WHERE TERM_GROUP_ID = #{termGroupId}
   AND TERM_ID       = #{termId}
   AND JNL_DATE      = #{baseDate}
   AND TR_TYPE NOT IN ('0131')
